\begin{proposition}[Exercise D.14: embedded $\varepsilon$-necks]
\label{prop:chow-ii-appd-embedded-epsilon-necks}
\dcref{appD:D.14}
\group{Rotational Neckpinches}
\source{chow-et-al-ricci-flow-part-ii:page-0390}
\uses{thm:chow-ii-appd-neckpinch-asymptotics}
For every $\varepsilon>0$, there is $t_\varepsilon<T$ such that
$(S^n,g(t))$ contains an embedded $\varepsilon$-neck whenever
$t\in(t_\varepsilon,T)$.
\end{proposition}

